// Scanner turns the bytes of a source into tokens.
type Scanner struct {
	// source is the bytes being scanned.
	source []byte

	// filePath is the file path the scanner was given.
	filePath string

	// token is the current token.
	token Token

	// lexemeStartIdx is the index of the first byte of the current token.
	lexemeStartIdx int

	// lexemeEndIdx is the index one past the last byte of the current token.
	lexemeEndIdx int

	// line is the line the current token starts on, counted from one.
	line int

	// column is the column the current token starts on, counted from one.
	column int
}

// NewScanner creates a scanner which turns the given bytes into tokens, starting at the first of them. The file path is
// used in error messages, so any string will do when the source is not a file.
func NewScanner(source []byte, filePath string) *Scanner {
	scanner := Scanner{
		filePath: filePath,
	}
	scanner.Reset(source, 0)
	return &scanner
}

// Token returns the current token.
func (s *Scanner) Token() Token {
	return s.token
}

// ByteOffset returns the start of the token in bytes from the start of the source. After Next returned false it is the
// offset one past the last byte.
func (s *Scanner) ByteOffset() int {
	return s.lexemeStartIdx
}

// Line returns the line the token starts on, counted from one.
func (s *Scanner) Line() int {
	return s.line
}

// Column returns the column the token starts on, counted from one.
func (s *Scanner) Column() int {
	return s.column
}

// Lexeme returns the bytes of the token, as a view into the source rather than a copy of it.
func (s *Scanner) Lexeme() []byte {
	return s.source[s.lexemeStartIdx:s.lexemeEndIdx]
}

// FilePath returns the file path the scanner was given.
func (s *Scanner) FilePath() string {
	return s.filePath
}

// Reset scans the given source from the given byte offset on. Useful for re-tokenizing the part of a source which
// changed.
func (s *Scanner) Reset(source []byte, offset int) {
	s.source = source

	s.lexemeStartIdx = 0
	// An offset past the end of the source would walk the line and column counters over bytes which are not
	// there. Clamping it leaves the scanner at the end of the source, where it reports the end token.
	s.lexemeEndIdx = min(offset, len(source))

	s.line = 1
	s.column = 1

	s.token = InvalidToken
}

// Next advances to the next token. Bytes which form no token become an invalid token. Returns false once the end of the
// source is reached, which sets the token to the end token.
func (s *Scanner) Next() bool {
	s.updateLineAndColumn(s.lexemeStartIdx, s.lexemeEndIdx)
	s.lexemeStartIdx = s.lexemeEndIdx

	var state uint32
	lexemePeekIdx := s.lexemeEndIdx
	for {
		// Remember every accepting state passed through, so the longest match wins over the first one.
		if token := acceptTokenByState[state]; token != InvalidToken {
			s.token = token
			s.lexemeEndIdx = lexemePeekIdx
		}
		if lexemePeekIdx == len(s.source) {
			// The end of the source is reached, so the state it stopped in was the last one to test.
			break
		}

		byteClass := byteClassByByte[s.source[lexemePeekIdx]]
		cellIdx := uint32(transitionBase[state]) + uint32(byteClass)
		if transitionCheck[cellIdx] != byteClass {
			// The state has no transition on this byte, so the token ends here.
			break
		}
		state = uint32(transitionNext[cellIdx])
		lexemePeekIdx++
	}

	if s.lexemeStartIdx < s.lexemeEndIdx {
		// We found a token.
		return true
	}

	if len(s.source) <= s.lexemeStartIdx {
		// We have reached the end of the source.
		s.token = EndToken
		return false
	}

	// We found some characters which do not form a token. The invalid token ends where the automaton stopped, because
	// the byte it could not consume is where the next attempt starts. Only when the automaton consumed nothing does it
	// cover that byte, which is what keeps the scan moving forward.
	s.token = InvalidToken
	s.lexemeEndIdx = max(s.lexemeStartIdx+1, lexemePeekIdx)
	return true
}

// updateLineAndColumn advances the line and column counters over the bytes between the two indexes.
func (s *Scanner) updateLineAndColumn(startIdx int, endIdx int) {
	for _, currByte := range s.source[startIdx:endIdx] {
		if currByte == '\n' {
			s.line++
			s.column = 1
		} else {
			s.column++
		}
	}
}
